using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Text;using SarmatVisionHold.KestrelClient.Models;using SarmatVisionHold.KestrelClient.Networking;using SarmatVisionHold.Vision;
namespace SarmatVisionHold.KestrelClient.Output { public sealed class SessionOutput:IDisposable {
 static readonly string RunId=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+"-"+System.Diagnostics.Process.GetCurrentProcess().Id;readonly string dir;readonly StreamWriter csv;readonly List<Row> rows=new List<Row>();readonly DateTime started=DateTime.UtcNow;public string DirectoryPath=>dir;
 public SessionOutput(string root,Guid id){dir=Path.Combine(Path.GetFullPath(root),id.ToString(),RunId);Directory.CreateDirectory(dir);Directory.CreateDirectory(Path.Combine(dir,"snapshots"));csv=new StreamWriter(Path.Combine(dir,"session.csv"),false,new UTF8Encoding(false));csv.WriteLine("simulation_timestamp,local_receive_timestamp,frame_number,latency_ms,position_x,position_y,position_z,velocity_world_x,velocity_world_y,velocity_world_z,velocity_body_x,velocity_body_y,velocity_body_z,roll,pitch,yaw,angular_x,angular_y,angular_z,wind_x,wind_y,wind_z,raw_x,raw_y,smoothed_x,smoothed_y,rotation,scale,tracked,inliers,quality,detected_class,expected_class,detected_direction,expected_direction,validation,processing_ms,matched,frame_without_telemetry,telemetry_without_frame,timestamp_mismatch,duplicate_frame,duplicate_telemetry,out_of_order");}
 public void Write(SynchronizedSample s,SparseOpticalFlowResult f,MotionDecision d,GroundTruthMotion g,ValidationResult v,double ms,SynchronizationCounters c){string F(double x)=>x.ToString("0.######",CultureInfo.InvariantCulture);var t=s.Telemetry;csv.WriteLine(string.Join(",",F(t.SimulationTimeSeconds),s.Frame.ReceivedUtc.ToString("O"),t.FrameNumber,F(s.NetworkLatencyMs),F(t.Position.X),F(t.Position.Y),F(t.Position.Z),F(t.VelocityWorld.X),F(t.VelocityWorld.Y),F(t.VelocityWorld.Z),F(t.VelocityBody.X),F(t.VelocityBody.Y),F(t.VelocityBody.Z),F(t.Attitude.RollRad),F(t.Attitude.PitchRad),F(t.Attitude.YawRad),F(t.AngularRateBody.X),F(t.AngularRateBody.Y),F(t.AngularRateBody.Z),F(t.WindWorld.X),F(t.WindWorld.Y),F(t.WindWorld.Z),F(f.TranslationX),F(f.TranslationY),F(d.SmoothedX),F(d.SmoothedY),F(f.RotationDegrees),F(f.Scale),f.TrackedPoints,f.InlierCount,F(f.Quality),d.SmoothedClass,g.Classification,d.TextureMotion,g.TextureDirection,v.Status,F(ms),c.Matched,c.FrameWithoutTelemetry,c.TelemetryWithoutFrame,c.TimestampMismatch,c.DuplicateFrame,c.DuplicateTelemetry,c.OutOfOrder));csv.Flush();rows.Add(new Row{Latency=s.NetworkLatencyMs,Processing=ms,Quality=f.Quality,Validation=v.Status,Expected=g.Classification,Detected=d.SmoothedClass});}
 public void SaveSnapshot(OpenCvSharp.Mat frame,uint number)=>OpenCvSharp.Cv2.ImWrite(Path.Combine(dir,"snapshots",$"frame-{number:D8}.jpg"),frame);
 public void Dispose(){csv.Dispose();using(var w=new StreamWriter(Path.Combine(dir,"report.md"),false,new UTF8Encoding(false))){w.WriteLine("# Kestrel live validation report\n");w.WriteLine($"- Started: {started:O}\n- Duration: {DateTime.UtcNow-started}\n- Matched samples: {rows.Count}\n- Average / p95 latency: {Avg(rows.Select(x=>x.Latency)):F2} / {Pct(rows.Select(x=>x.Latency),.95):F2} ms\n- Average / p95 processing: {Avg(rows.Select(x=>x.Processing)):F2} / {Pct(rows.Select(x=>x.Processing),.95):F2} ms\n- Average quality: {Avg(rows.Select(x=>x.Quality)):F3}");foreach(ValidationStatus s in Enum.GetValues(typeof(ValidationStatus)))w.WriteLine($"- {s}: {rows.Count(x=>x.Validation==s)}");}}
 static double Avg(IEnumerable<double> x)=>x.Any()?x.Average():0;static double Pct(IEnumerable<double> x,double p){var a=x.OrderBy(v=>v).ToArray();return a.Length==0?0:a[(int)Math.Min(a.Length-1,Math.Ceiling(p*a.Length)-1)];}sealed class Row{public double Latency,Processing,Quality;public ValidationStatus Validation;public ExpectedMotion Expected;public string Detected;}
 } }
